    L.push(`YOU ARE: ${unitName()} (${UNITS[ctl.unit].freq}). Pilot's radio is on ${com.active} = ${tuned ? (PK.gndName && tuned === 'GND' ? gndName(com.active) : UNITS[tuned].name) : 'no ATC unit'}${oldCh ? ` — the PREVIOUS channel: he has not switched yet. Answer only as the station on ${com.active}: "contact ${UNITS[ctl.unit].name} ${sayFreq(UNITS[ctl.unit].freq)}" (handoff_to ${ctl.unit}); no other instruction` : tuned === ctl.unit ? ' (pilot hears you)' : ' (pilot does NOT hear you)'}. Pilot ${ctl.checkedIn ? 'has' : 'has NOT yet'} called you on this frequency.`);
