    s = s.replace(/\b([A-Z]{3,5})\s?(\d)([A-Z])\b/g, (m, a, b, c) => sayProc(a + ' ' + b + c));
    s = s.replace(/\b([A-Z])(\d{1,2})([EW]?)\b/g, (m) => sayTaxiway(m));
    s = s.replace(/\b(\d+)([A-Z])\b/g, (m0, d, l) => `${sayDigits(d)} ${sayTaxiway(l)}`);
    s = s.replace(/\d+/g, (m0) => sayDigits(m0));
    s = s.replace(/\s{2,}/g, ' ');
