    out = out.replace(/,?\s*callsign only,?/gi, ',').replace(/,\s*,/g, ',')
      .replace(/\b(contact\s+[A-Za-z' ]+?),\s*(?=(?:zero|one|two|three|four|five|six|seven|eight|niner|nine)\b)/gi, '$1 ');
