    if (s.approach_cleared) { if (ctl.ga) ctl.ga.done = true; if (!ctl.approachCleared) flog(`cleared ILS approach runway ${settings.arrRwy}`); ctl.approachCleared = true; ctl.vecHdg = null; ctl.holding = false; }
