    if (!ctl || !ctl.taxi || ctl.taxi.kind !== 'dep' || !ctl.taxi.holdP || !AP || !t || !t.p) return null;
    const d = AP.dist(t.p, ctl.taxi.holdP), gs = t.gs ?? 0, ms = gs * 0.5144;
    if (d < 90 && gs < 12) return { d: Math.round(d), s: 0, at: true };
