          if (ctl.orbit && ctl.orbit.done && !ctl.orbit.told && fireOnce('orbitdone', `The orbit for descent is completed (now ${fmtAlt(t.altFt)}): ${ctl.vecHdg !== null && angleDiff(v.hdg, ctl.vecHdg) < 6 ? `the heading given before the orbit still works — no transmission needed (silent).` : `continue the vectors — advised heading ${String(Math.round(norm360(v.hdg - MAG_VAR) / 5) * 5 || 360).padStart(3, '0')}${v.phase === 'intercept' ? ' (intercept heading, with the approach clearance)' : ''}.`}`)) { ctl.orbit.told = true; return; }
