              if (fireOnce('xtm:' + rid, `STILL TOO HIGH, even with an expedited descent (${fmtAlt(t.altFt)}, ~${Math.round(hc.toJoin)} track miles to the join): the downwind is extended — "${ctl.expedited ? '' : 'descend ' + sayAlt(hc.jAlt) + ', expedite descent, '}I'll give you extra track miles for the descent"${ctl.expedited ? '' : ` (cleared_altitude_ft ${hc.jAlt})`}. The heading stays; the turn back comes later (the script calls you).`)) { ctl.expedited = true; return; }
