  function lfpgTaxiBias(kind) {
    const cfg = lfpgCfg(), own = (LFPG_FLOWS[cfg] || {})[kind === 'in' ? 'ARR' : 'DEP'] || {}, other = (LFPG_FLOWS[cfg] || {})[kind === 'in' ? 'DEP' : 'ARR'] || {};
    return (e, from, to, k) => {
      const x = edgeCrossesRunway(e);
      let w = e.name ? 1 : 1.3;   // prefer named taxiways/connectors: a clearance can only name those
      if (k !== undefined) {
        const fwd = from === e.a ? 1 : -1;
        const f = own[k], g = other[k];
        if (f !== undefined) w *= f === 0 ? 0.9 : f === fwd ? 0.75 : 3;      // with the flow / against it
        else if (g !== undefined && g !== 0 && g !== fwd) w *= 1.5;             // head-on with the other flow
      }
      if (!x) return w;
      const active = x.some((d) => rwyState.dep.includes(d) || rwyState.arr.includes(d));
      return [w, active ? 4000 : 600];
    };
  }
